  // ---------- The Apex Grind: a hustle podcast. Brayden commits to a bit and will not let it go. ----------
  podcasts: [
    {show:"The Apex Grind with Brayden Kolt", title:"Episode two hundred and six. Cold exposure.",
     cast:{brayden:{name:"Brayden Kolt",accent:"american",pitch:1.1,rate:1.15},tanner:{name:"Tanner",accent:"american",pitch:.85,rate:1}},
     lines:[
      ["brayden","What is up, Apex Nation. Brayden Kolt. Tanner's here. Today we're talking cold exposure."],
      ["tanner","Love cold exposure."],
      ["brayden","Every morning I get in a bathtub full of Sprite."],
      ["tanner","Like, the soda?"],
      ["brayden","It's not about the Sprite, Tanner. It's about the discipline."],
      ["tanner","Is it cold, though? Is the Sprite cold?"],
      ["brayden","I get it from the gas station that keeps it in the warm case. That's where the real ones get it."],
      ["tanner","So it's a warm bath. Of Sprite."],
      ["brayden","It's a cold plunge, Tanner. The cold is mental. I put the cold in. With my mind."],
      ["tanner","Doesn't it get sticky?"],
      ["brayden","Sticky is a mindset! You think the lion is worried about sticky? The lion is covered in Sprite all day!"],
      ["tanner","I don't think lions are..."],
      ["brayden","Every single lion, Tanner. Look it up. Don't look it up. We're not looking things up on this show."],
      ["pause",600],
      ["brayden","This episode is brought to you by Grind Shake. Forty grams of protein and a little bit of gravel. For texture. Use code APEX."],
      ["tanner","Is the gravel..."],
      ["brayden","The gravel is where the protein lives, Tanner."]]},
    {show:"The Apex Grind with Brayden Kolt", title:"Episode two hundred and eleven. The five A M club.",
     cast:{brayden:{name:"Brayden Kolt",accent:"american",pitch:1.1,rate:1.15},tanner:{name:"Tanner",accent:"american",pitch:.85,rate:1}},
     lines:[
      ["brayden","Apex Nation. Five A M club. If you're not up at five, somebody else is eating your lunch."],
      ["tanner","You get up at five?"],
      ["brayden","Every day. Five. Boom. Feet on the floor."],
      ["tanner","Because I texted you at like noon yesterday and you said you were asleep."],
      ["brayden","Yeah. Because it wasn't five yet."],
      ["tanner","Five in the morning?"],
      ["brayden","Five A M. After Midday. That's what A M stands for."],
      ["tanner","That's not what it..."],
      ["brayden","The early bird gets the worm, Tanner. I let the early bird get the worm. Then I get up at five and I take the worm from the bird. That's the game."],
      ["tanner","You take it from the bird?"],
      ["brayden","I'm not proud of it. Yes I am. I'm very proud of it. I have a lot of worms."],
      ["tanner","Where do you keep them?"],
      ["brayden","Wow. Okay. We're done with this segment. Somebody pull the segment. Pull it."],
      ["pause",500],
      ["brayden","Today's episode is sponsored by Alpha Lid. It's a hat. For your other hat. Code APEX gets you a third hat."]]},
    {show:"The Apex Grind with Brayden Kolt", title:"Episode two hundred and fourteen. Mentorship, with special guest Gil.",
     cast:{brayden:{name:"Brayden Kolt",accent:"american",pitch:1.1,rate:1.15},tanner:{name:"Tanner",accent:"american",pitch:.85,rate:1},gil:{name:"Gil",accent:"gloomy",pitch:.7,rate:.85}},
     lines:[
      ["brayden","Apex Nation, huge episode. I brought my mentor. This is Gil. Gil sold a boat."],
      ["gil","It was a pontoon."],
      ["brayden","Gil sold a pontoon boat. In one weekend. Tell them how, Gil."],
      ["gil","My wife made me."],
      ["brayden","Accountability partner! Gil had an accountability partner. That's mindset."],
      ["tanner","Gil, what would you tell somebody starting out?"],
      ["gil","Don't buy a pontoon."],
      ["brayden","Don't buy the pontoon. Be the pontoon. That's what he's saying."],
      ["gil","I'm not saying that."],
      ["brayden","He's saying it with his eyes, Tanner. Look at his eyes. Gil, look at Tanner."],
      ["gil","I'd like to go home now."],
      ["brayden","Gil's going home to grind. He grinds at home. Give it up for Gil, everybody."],
      ["tanner","There's no audience."],
      ["brayden","There's always an audience, Tanner. The audience is the guy you used to be."]]},
    {show:"The Apex Grind with Brayden Kolt", title:"Episode two hundred and twenty. Dressing for the room.",
     cast:{brayden:{name:"Brayden Kolt",accent:"american",pitch:1.1,rate:1.15},tanner:{name:"Tanner",accent:"american",pitch:.85,rate:1}},
     lines:[
      ["brayden","Apex Nation. You never wear a brimmed hat in a meeting. A brim tells the room you're hiding something."],
      ["tanner","Okay. Makes sense."],
      ["brayden","That's why I wear a hat with three brims. It tells the room I'm hiding three things."],
      ["tanner","Why would you want them to know that?"],
      ["brayden","Leverage. Now they have to guess which three."],
      ["tanner","What are the three things?"],
      ["brayden","I'm not gonna tell you on the podcast, Tanner. That's the whole point of the brims."],
      ["tanner","Is one of them that you lost the house?"],
      ["brayden","I didn't lose the house. I liquidated a non-performing asset into my car."],
      ["tanner","So you live in the car."],
      ["brayden","I live in a mobile headquarters. With a sunroof. Which I use as a fourth brim."],
      ["pause",500],
      ["brayden","Shout out to our sponsor, Founder Fog. It's a candle that smells like a meeting that should have been an email. Code APEX."]]},
    {show:"The Apex Grind with Brayden Kolt", title:"Episode two hundred and twenty three. Passive income.",
     cast:{brayden:{name:"Brayden Kolt",accent:"american",pitch:1.1,rate:1.15},tanner:{name:"Tanner",accent:"american",pitch:.85,rate:1}},
     lines:[
      ["brayden","Apex Nation. Passive income. I make money while I sleep."],
      ["tanner","How?"],
      ["brayden","I sell my sleep."],
      ["tanner","To who?"],
      ["brayden","There's a guy. He comes over. He watches me sleep. Four dollars an hour."],
      ["tanner","Brayden, that sounds like a guy who breaks into your car."],
      ["brayden","He's an investor, Tanner. He sits in the passenger seat and he invests his attention in my sleep."],
      ["tanner","Does he pay you?"],
      ["brayden","He pays me in exposure. He tells people about my sleep."],
      ["tanner","So he doesn't pay you."],
      ["brayden","I've never been richer. I've never been more seen. I need to go lie down. That's money, baby."]]},
  ],

